export function fetchArticle (articleId) {
  const origin = typeof window === 'undefined' ? 'http://localhost:3000' : window.location.origin
  return fetch(`${origin}/api/articles/${articleId}`).then((response) => response.json())
}

import { defineStore } from '@mpxjs/pinia'
import { fetchArticle } from '../services/article'

export const useArticleStore = defineStore('article', {
  state: () => ({
    article: null,
    recommendations: []
  }),
  actions: {
    async loadArticle (articleId, requestContext) {
      if (this.article) return
      const data = await fetchArticle(articleId, requestContext)
      this.article = data.article
      this.recommendations = data.recommendations
    }
  }
})

module.exports = {
  publicPath: '/',
  pluginOptions: {
    mpx: {
      plugin: {
        webConfig: {
          useSSR: false,
          routeConfig: { mode: 'hash', base: '/' }
        }
      }
    }
  }
}

import { defineStore } from '@mpxjs/pinia'
import { fetchArticle } from '../services/article'

export const useArticleStore = defineStore('article', {
  state: () => ({
    articleId: '',
    article: null,
    recommendations: [],
    loaded: false,
    requestVersion: 0
  }),
  actions: {
    async loadArticle (articleId, requestContext) {
      const normalizedArticleId = String(articleId || '')
      if (this.loaded && this.articleId === normalizedArticleId) return

      const requestVersion = ++this.requestVersion
      this.articleId = normalizedArticleId
      this.article = null
      this.recommendations = []
      this.loaded = false

      const data = await fetchArticle(normalizedArticleId, requestContext)
      if (requestVersion !== this.requestVersion || this.articleId !== normalizedArticleId) return

      this.article = data.article
      this.recommendations = data.recommendations || []
      this.loaded = true
    }
  }
})

import mpx from '@mpxjs/core'

function getRequestOrigin (requestContext) {
  const request = requestContext && requestContext.req
  if (!request) return ''

  const headers = request.headers || {}
  const forwardedProtocol = String(headers['x-forwarded-proto'] || '').split(',')[0].trim()
  const forwardedHost = String(headers['x-forwarded-host'] || '').split(',')[0].trim()
  const protocol = forwardedProtocol || (request.socket && request.socket.encrypted ? 'https' : 'http')
  const host = forwardedHost || headers.host

  if (!host) throw new Error('SSR request host is missing')
  return `${protocol}://${host}`
}

function fetchArticleInMiniProgram (url) {
  return new Promise((resolve, reject) => {
    mpx.request({
      url,
      usePromise: false,
      success (response) {
        if (response.statusCode >= 200 && response.statusCode < 300) {
          resolve(response.data)
          return
        }
        reject(new Error(`Article request failed with status ${response.statusCode}`))
      },
      fail: reject
    })
  })
}

export function fetchArticle (articleId, requestContext) {
  const path = `/api/articles/${encodeURIComponent(articleId)}`

  if (__mpx_mode__ !== 'web') return fetchArticleInMiniProgram(path)

  const origin = getRequestOrigin(requestContext)
  return fetch(origin ? `${origin}${path}` : path).then((response) => {
    if (!response.ok) throw new Error(`Article request failed with status ${response.status}`)
    return response.json()
  })
}

module.exports = {
  publicPath: '/content/',
  pluginOptions: {
    mpx: {
      plugin: {
        webConfig: {
          useSSR: true,
          routeConfig: { mode: 'history', base: '/content/' }
        }
      }
    }
  }
}
